  ('axiomatic-storm','Axiomatic Storm','22','Spell Compendium p. 22.','conjuration','Creation','1 standard action','standard','See rules text',NULL,'Cylinder (20-ft. radius, 20 ft. high)',NULL,'1 round/level (D)','None',NULL,'no','No'),
